 */

/*
 * Copy-first port of
 * node_modules/@salesforce/retail-react-app/app/components/product-item/product-quantity-picker.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
 * plan step 2.1). Zero functional diff at this step beyond the TypeScript annotations below and
 * the temporary `[overrides]` console.log marker.
 *
 * `onItemQuantityChange`'s return is typed `any` rather than `Promise<boolean>`: the base file's
 * own default for this callback (see index.tsx's `onItemQuantityChange = noop`, where `noop` is
 * a synchronous `() => {}`) does not actually satisfy the `.then(...)` call below either — the
 * base file itself gives no compile-time guarantee here, so `any` matches that gap rather than
 * inventing a stricter contract the base doesn't itself enforce.
 *
 * `quantity-picker` is not overridden anywhere in this repo (verified by directory listing at
 * time of writing), so it stays on the base `@salesforce/retail-react-app/...` path.
 */
import React from 'react'
import {FormattedMessage, useIntl} from 'react-intl'
import {Text, VisuallyHidden} from '@salesforce/retail-react-app/app/components/shared/ui'
import QuantityPicker from '@salesforce/retail-react-app/app/components/quantity-picker'

// See item-variant/index.tsx's own note on why this is `any` rather than a structural type.
type SfccProduct = any

type ProductQuantityPickerProps = {
    product: SfccProduct
    onItemQuantityChange: (quantity: number) => any
    stepQuantity: number
    quantity: number | string
    setQuantity: (quantity: number | string) => void
}

const ProductQuantityPicker = ({
    product,
    onItemQuantityChange,
    stepQuantity,
    quantity,
    setQuantity
}: ProductQuantityPickerProps) => {
    console.log('[overrides] product-quantity-picker.tsx')
    const intl = useIntl()

    const handleQuantityChange = (stringValue: string, numberValue: number) => {
        // Set the Quantity of product to value of input if value number
        if (numberValue >= 0) {
            // Call handler
            onItemQuantityChange(numberValue).then(
                (isValidChange: boolean) => isValidChange && setQuantity(numberValue)
            )
        } else if (stringValue === '') {
            // We want to allow the use to clear the input to start a new input so here we set the quantity to '' so NAN is not displayed
            // User will not be able to add '' quantity to the cart due to the add to cart button enablement rules
            setQuantity(stringValue)
        }
    }

    const handleQuantityBlur = (e: React.FocusEvent<HTMLInputElement>) => {
        // Default to last known quantity if a user leaves the box with an invalid value
        const {value} = e.target

        if (!value) {
            setQuantity(product.quantity)
        }
    }

    return (
        <>
            <Text
                fontSize="sm"
                color="gray.700"
                aria-label={intl.formatMessage(
                    {
                        id: 'item_variant.quantity.label',
                        defaultMessage:
                            'Quantity selector for {productName}. Selected quantity is {quantity}'
                    },
                    {
                        quantity: product?.quantity,
                        productName: product?.name
                    }
                )}
            >
                <FormattedMessage defaultMessage="Quantity:" id="product_item.label.quantity" />
            </Text>
            <QuantityPicker
                step={stepQuantity}
                value={quantity}
                min={0}
                clampValueOnBlur={false}
                onBlur={handleQuantityBlur}
                onChange={handleQuantityChange}
                productName={product?.name}
            />
            <VisuallyHidden role="status">
                {product?.name}
                {intl.formatMessage(
                    {
                        id: 'item_variant.assistive_msg.quantity',
                        defaultMessage: 'Quantity {quantity}'
                    },
                    {
                        quantity: product?.quantity
                    }
                )}
            </VisuallyHidden>
        </>
    )
}

export default ProductQuantityPicker

